-- Retire the legacy learning-events feature. Historical migration 0031 remains immutable.
PRAGMA foreign_keys = ON;

-- Remove only notifications generated by learning events and their delivery records.
DELETE FROM notification_dispatch_queue
WHERE notification_target_id IN (
  SELECT nt.id FROM notification_targets nt
  JOIN announcements a ON a.id = nt.announcement_id
  WHERE a.learning_event_id IS NOT NULL
);
DELETE FROM notification_targets
WHERE announcement_id IN (SELECT id FROM announcements WHERE learning_event_id IS NOT NULL);
DELETE FROM announcements WHERE learning_event_id IS NOT NULL;

DROP INDEX IF EXISTS idx_announcements_learning_event;
DROP INDEX IF EXISTS idx_learning_event_completions_student;
DROP INDEX IF EXISTS idx_learning_events_status_publish;
DROP TABLE IF EXISTS learning_event_completions;
DROP TABLE IF EXISTS learning_events;
ALTER TABLE announcements DROP COLUMN learning_event_id;

-- Content formerly called events in the app is now presented as activities.
UPDATE comments SET content_type='activity' WHERE content_type='event';
UPDATE reactions SET content_type='activity' WHERE content_type='event';
